import {rooms,baseCosts,phases,roomTotal,baseTotal,reserve,total} from './data.js';
const money=n=>'$'+new Intl.NumberFormat('en-US').format(Math.round(n));
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const root=document.querySelector('main');
document.querySelector('.hero-stats').innerHTML=`<div><span>UMUMIY BUDJET · TAXMINIY</span><strong>${money(total)}</strong></div><div><span>UMUMIY MUDDAT · TAXMINIY</span><strong>18 <small>oy</small></strong></div><div><span>MAKONLAR</span><strong>14 <small>ta</small></strong></div>`;
const hero=document.querySelector('.hero');
hero.insertAdjacentHTML('beforeend',`<div class="hero-view-control"><button class="view-switch" id="open-model" type="button"><span class="orbit-icon">◌</span> 360° maket <span>↗</span></button><span>Rasmga asoslangan taxminiy model</span></div><div class="hero-phases">Poydevor <span>—</span> Devor <span>—</span> Tom <span>—</span> Pardoz</div>`);
rooms.forEach((r,i)=>root.insertAdjacentHTML('beforeend',`<section class="room scene ${i%2?'reverse':''}" id="${r.id}" data-title="${r.name}"><div class="room-visual"><div class="room-image-frame"><picture><source media="(max-width: 600px)" srcset="assets/${r.id}-640.webp"><img src="assets/${r.id}.webp" alt="${r.name}: ${r.description}" loading="lazy" decoding="async" width="1280" height="854"></picture></div><div class="image-caption"><span>BALLET RESIDENCE</span><span>${String(i+1).padStart(2,'0')} / 14</span></div></div><div class="room-info"><span class="eyebrow">${String(i+1).padStart(2,'0')} · INTERYERLAR TO‘PLAMI</span><h2>${r.name}</h2><p class="room-subtitle">${r.subtitle}</p><p class="room-description">${r.description}</p><div class="room-facts"><span><b>${r.area}</b> m² <small>taxminiy</small></span><span><b>${r.days}</b> kun <small>taxminiy</small></span></div><div class="room-budget"><span>JIHOZLASH VA PARDOZ · TAXMINIY</span><strong data-counter="${r.cost.reduce((a,b)=>a+b,0)}">${money(r.cost.reduce((a,b)=>a+b,0))}</strong></div><dl class="cost-list">${['Materiallar','Ishchi kuchi','Mebel va jihozlar','Elektr va santexnika'].map((x,j)=>`<div><dt>${x}</dt><dd>${money(r.cost[j])}</dd></div>`).join('')}</dl><div class="materials"><span>TAVSIYA ETILGAN MATERIALLAR</span><p>${r.materials.join(' <i>·</i> ')}</p></div><a class="next-room" href="#${rooms[i+1]?.id||'budget'}">${i===rooms.length-1?'Umumiy hisobni ko‘rish':'Keyingi makon'} <span>↓</span></a></div></section>`));
root.insertAdjacentHTML('beforeend',`<section class="budget-section scene" id="budget" data-title="Xarajatlar"><div class="section-heading"><div><span class="eyebrow">15 · OCHIQ HISOB</span><h2>Har bir detal.<br><em>Aniq bir reja.</em></h2></div><p>Barcha summalar AQSH dollarida ko‘rsatilgan namuna hisoblaridir. Haqiqiy smeta o‘lchov, loyiha va material tanlovidan keyin belgilanadi.</p></div><div class="budget-layout"><div class="budget-table-wrap"><table><caption>Xonalar uchun taxminiy xarajatlar</caption><thead><tr><th scope="col">Makon</th><th scope="col">Maydon</th><th scope="col">Muddat</th><th scope="col">Summa, USD</th></tr></thead><tbody>${rooms.map(r=>`<tr><th scope="row"><a href="#${r.id}">${r.name}</a></th><td>${r.area} m²</td><td>${r.days} kun</td><td>${money(r.cost.reduce((a,b)=>a+b,0))}</td></tr>`).join('')}</tbody><tfoot><tr><th colspan="3" scope="row">Xonalar jami</th><td>${money(roomTotal)}</td></tr></tfoot></table></div><aside class="budget-summary glass"><span class="eyebrow">TO‘LIQ LOYIHA · TAXMINIY</span><h3>${money(total)}</h3><p>Qurilish, interyer va obodonlashtirish uchun namuna budjet.</p><dl>${baseCosts.map(([s,n])=>`<div><dt>${s}</dt><dd>${money(n)}</dd></div>`).join('')}<div><dt>Xonalar pardoz va jihozlari</dt><dd>${money(roomTotal)}</dd></div><div><dt>Zaxira · 10%</dt><dd>${money(reserve)}</dd></div></dl><p class="estimate-note">Yer xaridi kiritilmagan. Soliq, ruxsatnoma va yetkazish xarajatlari alohida aniqlanadi. Bu pudratchining tijoriy taklifi emas.</p><a href="tel:+998940103242" class="solid-button">Smetani muhokama qilish <span>↗</span></a></aside></div></section>
<section class="timeline-section scene" id="timeline" data-title="Jarayon"><div class="section-heading"><div><span class="eyebrow">16 · G‘OYADAN KALITGACHA</span><h2>Vaqt bilan<br><em>qiymatga aylanadi.</em></h2></div><div class="timeline-total"><strong>18</strong><span>oylik taxminiy reja</span></div></div><div class="timeline-chart"><div class="timeline-axis"><span>Bosqich</span><div>${[1,3,6,9,12,15,18].map(n=>`<span>${n}-oy</span>`).join('')}</div></div>${phases.map((p,i)=>`<div class="timeline-row"><div class="timeline-label"><span>0${i+1}</span><div><h3>${p.name}</h3><p>${p.detail}</p></div></div><div class="timeline-track"><div class="timeline-bar" style="--start:${p.start/18*100}%;--length:${p.length/18*100}%"><span>${p.months}</span></div></div></div>`).join('')}</div><p class="timeline-note">Xonalar ustida ishlar parallel olib boriladi, shuning uchun kunlar yig‘indisi umumiy muddatga teng emas. Reja maydon, jamoa va yetkazib berishga qarab yangilanadi.</p></section>
<section class="contact-section scene" id="contact" data-title="Bog‘lanish"><img class="contact-image" src="assets/rooftop.webp" alt="Ballet Residence tom ayvonidan quyosh botishi" loading="lazy" width="1280" height="854"><div class="contact-shade"></div><div class="contact-copy"><span class="eyebrow">17 · BIRINCHI QADAM</span><h2>Orzudagi uyingiz<br><em>suhbatdan boshlanadi.</em></h2><p>Loyiha, materiallar va sizga mos budjetni birga muhokama qilamiz.</p><a class="contact-number" href="tel:+998940103242">+998 94 010 32 42 <span>↗</span></a><a class="solid-button" href="tel:+998940103242">Qo‘ng‘iroq qilish <span>↗</span></a></div><footer><a class="brand" href="#residence"><span>BALLET<small>RESIDENCE</small></span></a><span>Arxitektura. Interyer. Hayot.</span><a href="#residence">Yuqoriga ↑</a></footer></section>`);
const nav=document.createElement('nav');nav.className='section-dots';nav.setAttribute('aria-label','Bo‘limlar bo‘ylab navigatsiya');
const sections=[...document.querySelectorAll('.scene')];
nav.innerHTML=sections.map((s,i)=>`<a href="#${s.id}" aria-label="${s.dataset.title||'Rezidensiya'}" ${i===0?'aria-current="location"':''}><span>${s.dataset.title||'Rezidensiya'}</span><i></i></a>`).join('');document.body.append(nav);
document.body.insertAdjacentHTML('beforeend','<div class="reading-progress" aria-hidden="true"><span></span></div><div class="cursor-glow" aria-hidden="true"></div><dialog class="model-dialog" aria-labelledby="model-title"><div class="model-heading"><div><span class="eyebrow">BALLET RESIDENCE</span><h2 id="model-title">Uyga boshqa tomondan qarang.</h2></div><button id="close-model" aria-label="360 darajali maketni yopish" type="button">×</button></div><div id="model-canvas"><p class="model-loading" role="status">3D maket yuklanmoqda…</p></div><div class="model-controls"><label>Aylantirish <input id="model-angle" type="range" min="-180" max="180" value="-16"></label><label>Yaqinlashtirish <input id="model-zoom" type="range" min="70" max="155" value="100"></label></div><p class="model-note">Sichqoncha yoki g‘ildirak bilan aylantiring. Yaqinlashtirish uchun boshqaruvdan foydalaning. Bu rasm asosida qurilgan taxminiy 3D maket; ko‘rinmagan tomonlar va o‘lchamlar farq qilishi mumkin.</p></dialog>');
document.documentElement.classList.add('enhanced');
const counterSeen=new WeakSet();function count(el){if(counterSeen.has(el))return;counterSeen.add(el);if(reduced.matches)return;const finish=+el.dataset.counter,start=performance.now()+1100;el.textContent='$0';function tick(t){const f=Math.max(0,Math.min((t-start)/1700,1));el.textContent=money(finish*(1-Math.pow(1-f,3)));if(f<1)requestAnimationFrame(tick);}requestAnimationFrame(tick);}
const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{entry.target.classList.toggle('in-view',entry.isIntersecting);if(entry.isIntersecting){entry.target.classList.add('revealed');entry.target.querySelectorAll('[data-counter]').forEach(count);}}),{threshold:.16});sections.forEach(s=>observer.observe(s));
let busy=false;function updateScroll(){busy=false;const h=innerHeight,y=scrollY,max=document.documentElement.scrollHeight-h;document.querySelector('.reading-progress span').style.transform=`scaleY(${max?y/max:0})`;let nearest=0,distance=Infinity;sections.forEach((s,i)=>{const rect=s.getBoundingClientRect(),d=Math.abs(rect.top);if(d<distance){distance=d;nearest=i;}if(!reduced.matches&&rect.top<h&&rect.bottom>0){s.style.setProperty('--scroll-shift',`${Math.max(-25,Math.min(25,rect.top/h*24))}px`);s.style.setProperty('--scroll-scale',1+Math.abs(rect.top/h)*.022);}});[...nav.children].forEach((a,i)=>{if(i===nearest)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});document.querySelector('.site-header').classList.toggle('scrolled',y>50);}
addEventListener('scroll',()=>{if(!busy){busy=true;requestAnimationFrame(updateScroll);}},{passive:true});updateScroll();
const glow=document.querySelector('.cursor-glow');let px=innerWidth/2,py=innerHeight/2,gx=px,gy=py;
document.addEventListener('pointermove',e=>{if(e.pointerType==='touch'||reduced.matches)return;px=e.clientX;py=e.clientY;glow.classList.add('visible');const frame=e.target.closest('.room-visual,.hero');if(frame){const b=frame.getBoundingClientRect();frame.style.setProperty('--tilt-y',`${((e.clientX-b.left)/b.width-.5)*3.5}deg`);frame.style.setProperty('--tilt-x',`${-((e.clientY-b.top)/b.height-.5)*2}deg`);}},{passive:true});
document.addEventListener('pointerout',e=>{const v=e.target.closest?.('.room-visual,.hero');if(v&&!v.contains(e.relatedTarget)){v.style.setProperty('--tilt-x','0deg');v.style.setProperty('--tilt-y','0deg');}});
let glowFrame;function animateGlow(){gx+=(px-gx)*.08;gy+=(py-gy)*.08;glow.style.transform=`translate(${gx-160}px,${gy-160}px)`;glowFrame=requestAnimationFrame(animateGlow);}if(!reduced.matches&&matchMedia('(pointer:fine)').matches)animateGlow();
document.addEventListener('visibilitychange',()=>{if(document.hidden)cancelAnimationFrame(glowFrame);else if(!reduced.matches&&matchMedia('(pointer:fine)').matches)animateGlow();});
const dialog=document.querySelector('.model-dialog');let model=null,modelPromise=null;
document.querySelector('#open-model').addEventListener('click',async()=>{dialog.showModal();document.body.style.overflow='hidden';if(!modelPromise){modelPromise=import('./model.js').then(m=>m.createModel(document.querySelector('#model-canvas'),document.querySelector('#model-angle'),document.querySelector('#model-zoom')));}
try{model=await modelPromise;model.start();}catch(e){document.querySelector('#model-canvas').innerHTML='<p class="model-loading" role="status">Bu qurilmada 3D ko‘rinish ochilmadi. Asosiy sahifada uy surati va barcha xonalarni ko‘rishingiz mumkin.</p>';modelPromise=null;}});
function closeModel(){dialog.close();}document.querySelector('#close-model').addEventListener('click',closeModel);dialog.addEventListener('click',e=>{if(e.target===dialog)closeModel();});dialog.addEventListener('close',()=>{document.body.style.overflow='';model?.stop();document.querySelector('#open-model').focus();});
